  let backPosition = GetBackPosition(rayStart);
  let dirVec = backPosition - start;
  var len = length(dirVec);
  if (!(len > 0.0) || len > 3.0) {
    discard;
    var dummy: FragmentOutput;
    return dummy;
  }
  let dir = dirVec / len;
  let texVox = params.volumeTexDimsFull.xyz;
  let lenVox = length(dirVec * texVox);
